function requireChatDb(env){if(!env.DB)throw Error('Chat database is unavailable.');return env.DB}
const chatUuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
async function chatTokenHash(token){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function chatSessionFields(row){return {id:row.id,nickname:row.nickname,visitorName:row.visitor_name,surface:row.surface,startedAt:row.started_at,updatedAt:row.updated_at,closedAt:row.closed_at,messageCount:Number(row.message_count||0)}}
async function createChatSession(env,body){const db=requireChatDb(env);const id=crypto.randomUUID(),token=[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join(''),hash=await chatTokenHash(token),now=new Date().toISOString(),nickname=(body.surface==='preview'?'Preview':'Audience')+'-'+id.slice(0,8);const visitorName=typeof body.visitorName==='string'?body.visitorName.trim():'';const statements=[db.prepare('INSERT INTO chat_sessions (id, token_hash, nickname, visitor_name, surface, started_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)').bind(id,hash,nickname,visitorName||null,body.surface||'live',now,now)];if(body.greeting)statements.push(db.prepare('INSERT INTO chat_messages (session_id,event_id,role,kind,content,created_at) VALUES (?, ?, ?, ?, ?, ?)').bind(id,crypto.randomUUID(),'assistant','greeting',body.greeting,now));await db.batch(statements);return {id,token,nickname,visitorName:visitorName||null,startedAt:now}}
async function authorizeChatSession(env,credential,surface){if(!credential||!chatUuid.test(credential.id||'')||typeof credential.token!=='string'||!/^[0-9a-f]{64}$/i.test(credential.token))return null;const row=await requireChatDb(env).prepare('SELECT * FROM chat_sessions WHERE id = ? AND token_hash = ?').bind(credential.id,await chatTokenHash(credential.token)).first();if(!row||row.closed_at||(surface&&row.surface!==surface))return null;return row}
async function chatEvent(env,session,body){const now=new Date().toISOString();const metadata=body.occurredAt?JSON.stringify({displayedAt:body.occurredAt}):null;await requireChatDb(env).batch([env.DB.prepare('INSERT OR IGNORE INTO chat_messages (session_id,event_id,role,kind,content,metadata_json,created_at) VALUES (?, ?, ?, ?, ?, ?, ?)').bind(session.id,body.eventId,body.kind==='name'?'system':'assistant',body.kind,body.content,metadata,now),env.DB.prepare('UPDATE chat_sessions SET updated_at = ?, visitor_name = CASE WHEN ? = 1 THEN ? ELSE visitor_name END WHERE id = ?').bind(now,body.visitorName===undefined?0:1,body.visitorName?.trim()||null,session.id)]);return {saved:true}}
function chatErrorText(context){const language=String(context.language==='auto'?context.displayLanguage||'English':context.language||'English').toLowerCase();if(language.includes('hinglish'))return 'Chat connect nahi ho paaya. Phir try karein.';if(language.includes('hindi'))return 'चैट कनेक्ट नहीं हो पाया। कृपया फिर कोशिश करें।';return 'The chat could not connect. Please try again.'}
