const action=requestedAction(political.question);const locale=context.language==='auto'?(/[\u0900-\u097f]/.test(question)?'Hindi':/\b(mujhe|hai|hain|chahiye|dekhne|bata|nahi)\b/i.test(question)?'Hinglish':body.context?.displayLanguage||'English'):context.language;let direct=political.political&&!political.question?'political':updated.local;if(!direct&&languageOnlyRequest(question))direct='language';if(!direct&&!customHappyPath(settings.happyPath)&&conversationState.tone==='normal'&&/^(?:hi|hello|hey|hey there|good (?:morning|afternoon|evening)|namaste|namaskar|नमस्ते|नमस्कार)[.!?\s]*$/i.test(question.trim()))direct='greeting';
